<?php require_once __DIR__.'/../includes/auth.php';$user=require_role('admin');
$stats=['users'=>admin_count('SELECT COUNT(*) FROM users'),'customers'=>admin_count("SELECT COUNT(*) FROM users WHERE role='customer'"),'providers'=>admin_count("SELECT COUNT(*) FROM users WHERE role='provider'"),'businesses'=>admin_count("SELECT COUNT(*) FROM users WHERE role='business'"),'verified'=>admin_count("SELECT (SELECT COUNT(*) FROM provider_profiles WHERE verification_status='verified')+(SELECT COUNT(*) FROM business_profiles WHERE verification_status='verified')"),'requests'=>admin_count('SELECT COUNT(*) FROM service_requests'),'completed'=>admin_count("SELECT COUNT(*) FROM service_requests WHERE status='completed'"),'pending'=>admin_count("SELECT COUNT(*) FROM service_requests WHERE status='pending'"),'reviews'=>admin_count("SELECT COUNT(*) FROM reviews WHERE status='published'"),'revenue'=>admin_count("SELECT COALESCE(SUM(amount),0) FROM payments WHERE status='paid'")];
$activity=db()->query('SELECT a.*,u.name actor FROM platform_activity a LEFT JOIN users u ON u.id=a.actor_id ORDER BY a.id DESC LIMIT 10')->fetchAll();$pageTitle='Admin Dashboard — LocalConnect';require __DIR__.'/../includes/header.php';?><div class="container py-4"><?php include __DIR__.'/_nav.php';?><h1 class="fw-bold mb-4">Admin dashboard</h1><div class="row g-3"><?php foreach($stats as $k=>$v):?><div class="col-6 col-lg-3"><div class="card h-100 shadow-sm border-0"><div class="card-body"><div class="text-muted text-capitalize"><?=e($k)?></div><div class="display-6 fw-bold"><?=number_format($v)?></div></div></div></div><?php endforeach;?></div><div class="card border-0 shadow-sm mt-4"><div class="card-body"><h4>Recent platform activity</h4><?php if(!$activity):?><p class="text-muted mb-0">No moderation activity yet.</p><?php else:?><div class="table-responsive"><table class="table"><tr><th>Action</th><th>Actor</th><th>Details</th><th>Time</th></tr><?php foreach($activity as $a):?><tr><td><?=e($a['action'])?></td><td><?=e($a['actor']??'System')?></td><td><?=e($a['details'])?></td><td><?=e($a['created_at'])?></td></tr><?php endforeach;?></table></div><?php endif;?></div></div></div><?php require __DIR__.'/../includes/footer.php';?>